import * as fs from "fs";
import * as path from "path";

export interface HeaderType {
  name: string;
  kind: "class" | "struct" | "enum" | "constant" | "typedef";
  members?: string[];
  values?: Record<string, string>;
}

const SYSTEM_PATH_MARKERS = [
  "msys64", "LLVM", "Windows Kits", "Microsoft Visual Studio",
  "usr/include", "usr/local/include", "mingw", "clang",
];

function isSystemHeader(filePath: string): boolean {
  const normalized = filePath.replace(/\\/g, "/");
  return SYSTEM_PATH_MARKERS.some((m) => normalized.includes(m));
}

function shouldKeepName(name: string): boolean {
  if (!name || name.startsWith("_") || name.startsWith("__")) return false;
  if (/^\d/.test(name)) return false;
  if (name === name.toUpperCase() && name.length < 3) return false;
  return true;
}

export function scanHeaders(headerFiles: string[]): HeaderType[] {
  const types: HeaderType[] = [];
  const seen = new Set<string>();

  for (const file of headerFiles) {
    if (isSystemHeader(file)) continue;
    let content: string;
    try {
      content = fs.readFileSync(file, "utf-8");
    } catch {
      continue;
    }
    extractTypes(content, types, seen);
  }

  return types;
}

function addType(types: HeaderType[], seen: Set<string>, t: HeaderType): void {
  if (!shouldKeepName(t.name)) return;
  if (seen.has(t.name)) return;
  seen.add(t.name);
  types.push(t);
}

function extractTypes(content: string, types: HeaderType[], seen: Set<string>): void {
  // Remove single-line comments
  const stripped = content.replace(/\/\/.*$/gm, "");
  // Remove multi-line comments
  const clean = stripped.replace(/\/\*[\s\S]*?\*\//g, "");

  // Enums: enum [class] Name { A [= val], B, ... }
  const enumRe = /\benum\s+(?:class\s+)?(\w+(?:::\w+)*)\s*\{([^}]*)\}/g;
  let m: RegExpExecArray | null;
  while ((m = enumRe.exec(clean)) !== null) {
    const name = m[1].replace(/::/g, "_");
    const body = m[2];
    const values: Record<string, string> = {};
    let idx = 0;
    for (const entry of body.split(",")) {
      const trimmed = entry.trim();
      if (!trimmed) continue;
      const eqMatch = trimmed.match(/^(\w+)\s*=\s*(.+)$/);
      if (eqMatch) {
        values[eqMatch[1]] = eqMatch[2].trim();
        const parsed = parseInt(eqMatch[2].trim(), 0);
        if (!isNaN(parsed)) idx = parsed + 1;
      } else {
        const nm = trimmed.match(/^(\w+)/);
        if (nm) { values[nm[1]] = String(idx); idx++; }
      }
    }
    addType(types, seen, { name, kind: "enum", values });
  }

  // Classes and structs with members
  const classRe = /\b(class|struct)\s+(\w+(?:::\w+)*)(?:\s*[:{][^;])/g;
  while ((m = classRe.exec(clean)) !== null) {
    const kind = m[1] as "class" | "struct";
    const name = m[2].replace(/::/g, "_");
    const startIdx = clean.indexOf("{", m.index + m[0].length - 1);
    const members: string[] = [];
    if (startIdx !== -1) {
      let depth = 1; let i = startIdx + 1;
      while (i < clean.length && depth > 0) {
        if (clean[i] === "{") depth++;
        else if (clean[i] === "}") depth--;
        i++;
      }
      const body = clean.slice(startIdx + 1, i - 1);
      const fieldRe = /(?:^|;|\{)\s*(?:(?:unsigned|signed|const|static|volatile|mutable|inline)\s+)*(?:\w+(?:::\w+)*(?:\s*[*&])*)\s+(\w+)\s*[;=\[]/gm;
      let fm: RegExpExecArray | null;
      while ((fm = fieldRe.exec(body)) !== null) {
        if (shouldKeepName(fm[1]) && !members.includes(fm[1])) members.push(fm[1]);
      }
    }
    addType(types, seen, { name, kind, members: members.length > 0 ? members : undefined });
  }

  // #define NAME value (simple numeric/string only)
  const defineRe = /^[ \t]*#define\s+(\w+)\s+((?:0x[\da-fA-F]+|[-]?\d+(?:\.\d+)?|"[^"]*"))\s*$/gm;
  while ((m = defineRe.exec(clean)) !== null) {
    addType(types, seen, { name: m[1], kind: "constant", values: { value: m[2] } });
  }

  // typedef ... Name;
  const typedefRe = /\btypedef\s+[\s\S]*?\b(\w+)\s*;/g;
  while ((m = typedefRe.exec(clean)) !== null) {
    addType(types, seen, { name: m[1], kind: "typedef" });
  }

  // const/constexpr/static const declarations
  const constRe = /\b(?:static\s+)?(?:const|constexpr)\s+\w+\s+(\w+)\s*=\s*([^;]+);/g;
  while ((m = constRe.exec(clean)) !== null) {
    addType(types, seen, { name: m[1], kind: "constant", values: { value: m[2].trim() } });
  }
}

export function generateTypeStubs(types: HeaderType[]): string {
  const lines: string[] = [
    "// Auto-generated type stubs from C/C++ headers",
    "// Do not edit — regenerated by header-scanner",
    "",
  ];
  const names: string[] = [];

  for (const t of types) {
    names.push(t.name);
    switch (t.kind) {
      case "class":
      case "struct":
        lines.push(`export class ${t.name} { [key: string]: any; constructor(...args: any[]) {} }`);
        break;
      case "enum":
        if (t.values && Object.keys(t.values).length > 0) {
          const entries = Object.entries(t.values)
            .map(([k, v]) => `  ${k}: ${/^[-]?\d/.test(v) ? v : JSON.stringify(v)}`)
            .join(",\n");
          lines.push(`export const ${t.name} = {\n${entries}\n} as const;`);
        } else {
          lines.push(`export const ${t.name} = {} as const;`);
        }
        break;
      case "constant": {
        const val = t.values?.value ?? "undefined";
        lines.push(`export const ${t.name}: any = ${val};`);
        break;
      }
      case "typedef":
        lines.push(`export type ${t.name} = any;`);
        break;
    }
    lines.push("");
  }

  if (names.length > 0) {
    lines.push("// Register all types on globalThis for runtime access");
    lines.push(`Object.assign(globalThis, { ${names.join(", ")} });`);
    lines.push("");
  }

  return lines.join("\n");
}
